// LAB: Read a bounded record slice
// Return a substring only when offset and length fit within the file model. An empty slice at end is valid; an offset past end is not.
// This starter verifies the original example. Extend it to satisfy the lab checks.
#include <cassert>
#include <cstddef>
#include <iostream>
#include <string>

int main() {
    const std::string file = "ABCDE";
    const std::size_t offset = 2;
    const std::size_t count = 3;
    assert(offset <= file.size() && count <= file.size() - offset);
    std::cout << file.substr(offset, count) << '\n';
}

#include <cassert>
#include <cstddef>
#include <iostream>
#include <limits>
#include <optional>
#include <string>

std::optional<std::string> read_slice(const std::string& file, std::size_t offset,
                                     std::size_t length) {
    if(offset > file.size() || length > file.size()-offset) return std::nullopt;
    return file.substr(offset,length);
}

int main() {
    assert(read_slice("ABCDE",2,3) == "CDE");
    assert(read_slice("ABCDE",5,0) == "");
    assert(!read_slice("ABCDE",6,0));
    assert(!read_slice("ABCDE",2,std::numeric_limits<std::size_t>::max()));
    std::cout << *read_slice("ABCDE",2,3) << " end-empty=valid\n";
}
